 roleLayer.innerHTML=`<div class="njRoleArt"></div><div class="njRoleVignette"></div><header class="njRoleHeader"><button data-r="map">← 返回地图</button><span>山河重光 / 南京受降</span><button data-r="motion" aria-pressed="true">动效：开</button><button data-r="restart">重新开始</button></header><nav class="njRoute" aria-label="体验流程"><span class="${outside?'active':''}">01 会场外交流</span><span>02 入场见证</span><span class="${outside?'':'active'}">03 胜利消息</span><span>04 连线与作业</span></nav><div class="njRoleTargets"></div><section class="njDialogue"><div class="njSpeaker"><b>${outside?'随行观察员':'街头见证者'}</b><span>教学角色 · 对话为教学虚构</span><small>${outside?'入场准备':'仪式结束后的消息传播'}</small></div><h2>${outside?'入场前，先把任务问清楚':'胜利的消息，传向街头'}</h2><p class="njDialogueText">${outside?'你来到南京受降会场外。向工作人员确认今天的仪式，再向记者请教如何记录历史。':'受降仪式结束后，消息通过广播等方式传播。听一听消息，再和市民聊聊：这场胜利意味着什么？'}</p><div class="njReplies"></div><div class="njSceneActions"><span class="njProgress"></span><button class="njPrimary" data-r="continue">${outside?'进入受降会场 →':'整理胜利时间线 →'}</button></div></section><small class="njRoleCredit">AI情境重构 · ${outside?'会场外交流为教学设计':'庆祝场景为概括性重构，不代表全国各地在同一时刻的实况'}</small>`;
